void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    float r = .1f;

    // uv in [0,1], radius = r
    // Let boxSize be the width/height from the center to the edges 
    //  (i.e. half your total desired rectangle), 
    //  but remember to subtract the corner radius so we can shape the corners properly.
    vec2 uvCenter = uv - vec2(0.5, 0.5);  // center rectangle at (0.5, 0.5)
    vec2 boxSize  = vec2(0.5 - r, 0.5 - r); 

    // 1) get how far uv is outside the box region (if any):
    vec2 d = abs(uvCenter) - boxSize;   
    // 2) clamp negative distances to 0, which means "still inside the box along that axis"
    float outsideDist = length(max(d, 0.0)); 
    // 3) subtract the corner radius
    float sdf = outsideDist - r;  

    // If sdf < 0, we’re inside; if sdf > 0, we’re outside.
    float mask = sdf < 0.0 ? 1.0 : 0.0;



    fragColor = vec4(1.0 * mask);
}
